using System;using System.Text.RegularExpressions;using System.IO;using System.Linq;using System.Text;using System.Collections;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;using System.Web.Script.Serialization;
public sealed class EvidenceWorkbench:UserControl {
 readonly string root;readonly ListBox list=new ListBox{Name="EvidenceResults",Dock=DockStyle.Fill,IntegralHeight=false};readonly RichTextBox detail=new RichTextBox{Name="EvidenceDetail",Dock=DockStyle.Fill,ReadOnly=true,DetectUrls=false};readonly TextBox query=new TextBox{Name="EvidenceQuery",Width=260};readonly ComboBox kind=new ComboBox{Name="EvidenceKind",DropDownStyle=ComboBoxStyle.DropDownList,Width=190};readonly Label summary=new Label{Name="EvidenceStatus",Dock=DockStyle.Top,Height=60,AutoEllipsis=true};readonly List<Row> rows=new List<Row>();Dictionary<string,object>graph;Dictionary<string,Dictionary<string,object>> materials=new Dictionary<string,Dictionary<string,object>>();
 public sealed class Row {public string Id,Kind,Label,Search,Text;public override string ToString(){return Label;}}
 static Dictionary<string,object>D(object x){return x as Dictionary<string,object>??new Dictionary<string,object>();}static object V(Dictionary<string,object>d,string k){return d.ContainsKey(k)?d[k]:null;}static string S(Dictionary<string,object>d,string k){return Convert.ToString(V(d,k));}static IEnumerable<object>A(object o){if(o is IEnumerable&&!(o is string)&&!(o is IDictionary))foreach(var x in (IEnumerable)o)yield return x;}static IEnumerable<Dictionary<string,object>>Items(Dictionary<string,object>d,string k){return A(V(d,k)).Select(D);}static string J(object o){return new JavaScriptSerializer{MaxJsonLength=8388608}.Serialize(o);}static string ShaFile(string p){return LocalResearchController.Hash(p).ToLowerInvariant();}
 static Dictionary<string,object>Read(string p){if(new FileInfo(p).Length>8388608)throw new InvalidDataException("Evidence file exceeds 8MiB");return new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Deserialize<Dictionary<string,object>>(File.ReadAllText(p,Encoding.UTF8));}
 public EvidenceWorkbench(string root,Action back){this.root=root;Dock=DockStyle.Fill;BackColor=Color.FromArgb(31,35,43);ForeColor=Color.White;list.BackColor=detail.BackColor=BackColor;list.ForeColor=detail.ForeColor=ForeColor;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};var close=new Button{Text="Назад к карточкам",AutoSize=true};close.Click+=(s,e)=>back();var rebuild=new Button{Text="Перестроить локальный индекс",Name="RebuildEvidence",AutoSize=true};rebuild.Click+=(s,e)=>Rebuild();bar.Controls.Add(close);bar.Controls.Add(new Label{Text="Поиск в сохранённом:",AutoSize=true,Padding=new Padding(0,7,0,0)});bar.Controls.Add(query);kind.Items.AddRange(new object[]{"Все материалы и гипотезы","Исходные сообщения","Документы альтернатив","Гипотезы модели","Ранние наблюдения","Ответы сообщества","Пакеты / SDK","Только метаданные","Ручные гипотезы","Ранние бизнес-гипотезы"});kind.Items.Add("Незавершённая работа редактора");kind.SelectedIndex=0;bar.Controls.Add(kind);bar.Controls.Add(rebuild);var manual=new Button{Text="Новая ручная гипотеза",Name="NewManualHypothesis",AutoSize=true};manual.Click+=(s,e)=>StartManual();bar.Controls.Add(manual);var split=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=340};split.Panel1.Controls.Add(list);split.Panel2.Controls.Add(detail);Controls.Add(split);Controls.Add(summary);Controls.Add(bar);list.SelectedIndexChanged+=(s,e)=>{var r=list.SelectedItem as Row;detail.Text=r==null?"Нет результатов локального поиска; это не отсутствие решений на рынке.":r.Text;};query.TextChanged+=(s,e)=>Filter();kind.SelectedIndexChanged+=(s,e)=>Filter();Reload();}
 void StartManual(){var selected=list.SelectedItem as Row;Dictionary<string,object>source=null;ManualHypotheses.Record previous=null;ManualDraftRecovery.Draft recovery=null;if(selected!=null&&selected.Kind=="recovery"){string issue;recovery=ManualDraftRecovery.Load(root,out issue).FirstOrDefault(x=>x.Id==selected.Id);if(recovery!=null){source=ManualHypotheses.D(ManualHypotheses.V(recovery.Data,"source_snapshot"));string prev=ManualHypotheses.S(recovery.Data,"previous_id");if(prev!=""){previous=ManualHypotheses.Load(root).Records.FirstOrDefault(x=>x.Id==prev);if(previous==null){detail.Text="Предыдущая ревизия отсутствует; восстановленная работа сохранена, фиксация заблокирована.";return;}}}}else if(selected!=null&&selected.Kind=="manual"){previous=ManualHypotheses.Load(root).Records.FirstOrDefault(r=>r.Id==selected.Id);if(previous!=null)source=ManualHypotheses.D(ManualHypotheses.V(previous.Data,"source_snapshot"));}else if(selected!=null)materials.TryGetValue(selected.Id,out source);if(source==null){detail.Text="Для новой ручной гипотезы выберите поле источника. Для новой ревизии выберите ручной черновик; прежняя запись сохранится.";return;}var parent=detail.Parent;var bar=Controls.OfType<FlowLayoutPanel>().Single();foreach(Control c in bar.Controls)c.Enabled=false;list.Enabled=false;detail.Visible=false;ManualHypothesisEditor editor=null;editor=new ManualHypothesisEditor(root,source,id=>{parent.Controls.Remove(editor);editor.Dispose();detail.Visible=true;list.Enabled=true;foreach(Control c in bar.Controls)c.Enabled=true;if(id!=null){kind.SelectedIndex=8;query.Text="";}Reload();if(id!=null)for(int i=0;i<list.Items.Count;i++)if(((Row)list.Items[i]).Id==id){list.SelectedIndex=i;break;}},previous,recovery);parent.Controls.Add(editor);editor.BringToFront();}
 void Rebuild(){try{string issue;string python=PortableRuntime.Python(root,"export",out issue);if(python==null)throw new Exception(issue);PortableRuntime.Run(python,PortableRuntime.Quote(Path.Combine(root,"evidence_workspace.py"))+" --root "+PortableRuntime.Quote(root),root,15000);Reload();}catch(Exception ex){summary.Text="Локальный индекс не перестроен: "+ex.Message+". Сеть и AI не запускались.";}}
 void Reload(){rows.Clear();materials.Clear();containers.Clear();try{var wrap=Read(Path.Combine(root,"evidence-workspace.json"));string payload=S(wrap,"payload_json");if(ProvenanceAudit.Sha(payload)!=S(wrap,"payload_sha256"))throw new InvalidDataException("Index payload hash mismatch");graph=new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Deserialize<Dictionary<string,object>>(payload);if(S(graph,"schema")!="reveng-evidence-workspace-v1")throw new InvalidDataException("Unsupported index schema");var inputs=D(V(graph,"inputs"));if(!inputs.ContainsKey("research-candidate-reviews.json")||!inputs.ContainsKey("research-output-cards.json"))throw new InvalidDataException("Required inputs missing");foreach(string name in inputs.Keys){if(name!="research-candidate-reviews.json"&&name!="research-output-cards.json"&&name!="candidates.json"&&name!="analysis-queue.json"&&name!="observation-index.json"&&name!="attribution-cases/cases.json"&&!Regex.IsMatch(name,@"^(analysis-inputs/[0-9a-f]{64}\.json|observation-snapshots/[0-9a-f]{64}\.json|attribution-cases/[a-z0-9][a-z0-9-]{0,63}-(catalog|output|input|response)\.json)$"))throw new InvalidDataException("Unexpected input path");if(V(inputs,name)==null){if(name!="research-candidate-reviews.json"||File.Exists(Path.Combine(root,name))||Directory.Exists(Path.Combine(root,name)))throw new InvalidDataException("Optional input appeared or required input is absent; rebuild the index");continue;}if(S(inputs,name)!=ShaFile(Path.Combine(root,name)))throw new InvalidDataException("Сохранённые данные изменились; перестройте локальный индекс");}foreach(var m in Items(graph,"materials")){if(ProvenanceAudit.Sha(S(m,"text"))!=S(m,"text_sha256")||materials.ContainsKey(S(m,"id")))throw new InvalidDataException("Material integrity mismatch");materials.Add(S(m,"id"),m);}foreach(var m in materials.Values){ValidateArchivedBindings(m);rows.Add(MaterialRow(m));}foreach(var h in Items(graph,"hypotheses"))rows.Add(HypothesisRow(h));foreach(var h in Items(graph,"legacy_hypotheses"))rows.Add(LegacyRow(h));string recoveryError=AddRecoveryRows();var manualNotes=ManualHypotheses.Load(root);foreach(var note in manualNotes.Records)rows.Add(new Row{Id=note.Id,Kind="manual",Label="Ручной черновик: "+ManualHypotheses.S(note.Data,"title"),Text=note.Text,Search=note.Text});if(manualNotes.Errors.Count>0)summary.Text="Ошибки ручных заметок: "+String.Join("; ",manualNotes.Errors)+". Повреждённые записи не исправлялись.";summary.Text=(recoveryError!=""?"Ошибка восстановления: "+recoveryError+"\r\n":"")+(manualNotes.Errors.Count>0?"Ошибки ручных заметок: "+String.Join("; ",manualNotes.Errors)+"\r\n":"")+(manualNotes.OriginWarnings.Count>0?"Связь источников части ручных заметок сейчас не подтверждена: "+manualNotes.OriginWarnings.Count+"\r\n":"")+"Локальный корпус: "+J(V(graph,"coverage"))+"\r\nОшибок версий: "+A(V(graph,"errors")).Count()+". Ручной разбор и гипотезы модели разделены; AUTO_ADMISSION=false.";Filter();}catch(Exception ex){rows.Clear();list.Items.Clear();detail.Text="Индекс недоступен: "+ex.Message+". Не исправляйте исходные свидетельства; можно перестроить только производный локальный индекс. AI/сеть не запускались.";summary.Text="Материалы не выданы за проверенные. "+ex.Message;AddRecoveryRows();Filter();}}
 string AddRecoveryRows(){string previous=ManualHypotheses.DescribePrevious(root);if(previous!="")rows.Add(new Row{Id="previous-manual-snapshot",Kind="previous_manual",Label="Previous manual notes / предыдущие заметки (только чтение)",Text=previous,Search=previous});string recoveryError;foreach(var draft in ManualDraftRecovery.Load(root,out recoveryError)){var f=D(V(draft.Data,"fields"));string text="Незавершённая работа редактора. НЕ сохранённая гипотеза, НЕ вывод модели, НЕ свидетельство спроса.\r\n"+J(draft.Data)+"\r\nЧтобы продолжить, выберите эту строку и нажмите «Новая ручная гипотеза».";rows.Add(new Row{Id=draft.Id,Kind="recovery",Label="Продолжить: "+S(f,"title"),Text=text,Search=text});}return recoveryError;}
 readonly Dictionary<string,Dictionary<string,object>> containers=new Dictionary<string,Dictionary<string,object>>();
 void ValidateArchivedBindings(Dictionary<string,object>m){EvidenceBindings.Check(root,m,false);foreach(var origin in Items(m,"origins")){string name=S(origin,"container"),field=S(origin,"source_field");if(!D(V(graph,"inputs")).ContainsKey(name))throw new InvalidDataException("Archived field container outside bound inputs");Dictionary<string,object>container;if(!containers.TryGetValue(name,out container)){container=Read(Path.Combine(root,name));containers.Add(name,container);}Dictionary<string,object>row;if(name.StartsWith("attribution-cases/",StringComparison.Ordinal)){var source=D(V(D(V(container,"sources")),S(origin,"evidence_id")));row=D(V(D(V(source,"fields")),field));string actual=row.ContainsKey("text")?S(row,"text"):S(row,"full_text");if(actual!=S(m,"text"))throw new InvalidDataException("Archived catalog text binding mismatch");}else{var matches=Items(container,"observations").Where(r=>S(r,"evidence_id")==S(origin,"evidence_id")&&S(r,"observation_id")==S(origin,"observation_id")).ToArray();if(matches.Length!=1||S(matches[0],field)!=S(m,"text"))throw new InvalidDataException("Archived observation text binding mismatch");}}}
 Row MaterialRow(Dictionary<string,object>m){string materialKind=S(m,"kind");bool original=materialKind=="original_post",document=materialKind=="provider_document";string category=original?"original":document?"document":materialKind=="community_answer"?"answer":materialKind=="package_listing"?"package":materialKind=="metadata_only"?"metadata":"archive";
 string label=original?"Исходное сообщение публичного разбора":document?"Документ альтернативы":category=="answer"?"Ответ сообщества — отдельный автор":category=="package"?"Описание пакета / SDK — не спрос":category=="metadata"?"Только метаданные — тело недоступно":materialKind=="archived_original"?"Архивное исходное сообщение":"Архивное поле — scope не установлен";
 var b=new StringBuilder(label+"\r\n");b.AppendLine("Тип/истинность: "+S(m,"epistemic_status")).AppendLine(S(m,"url")).AppendLine("Автор/издатель: "+S(m,"author")).AppendLine("Роль: "+S(m,"role")+" | поле: "+S(m,"source_field")).AppendLine("Получено: "+EvidenceDates.Display(V(m,"captured_at"))+" | опубликовано: "+EvidenceDates.Display(V(m,"published_at"))).AppendLine("Материал revision: "+S(m,"id")).AppendLine("Текст SHA256: "+S(m,"text_sha256")+" | response SHA256: "+S(m,"response_sha256")).AppendLine("Область текста: "+S(m,"text_scope")).AppendLine("Версии исследования: "+J(V(m,"version_ids"))).AppendLine("Происхождение — E-ID локален этому контейнеру: "+J(V(m,"origins"))).AppendLine("Связанные гипотезы: "+J(V(m,"card_ids")));
 if(original){var analyses=Items(graph,"analyses").Where(x=>S(x,"original_id")==S(m,"id")).ToArray();if(analyses.Length==0)b.AppendLine("ЭТОТ СНИМОК ЕЩЁ НЕ РАЗОБРАН. Сбор материала не является AI-анализом; прежний ручной разбор не перенесён на новую ревизию. Можно создать отдельную ручную гипотезу.");foreach(var a in analyses)AppendAnalysis(b,a);}else if(document)b.AppendLine("Документ может быть связан прежней маршрутизацией без соответствия задаче. Смотрите вывод в исходном сообщении, а не счётчик документов.");else b.AppendLine("Поле найдено в сохранённом контейнере. Разбор других ревизий или чужого ответа не перенесён сюда; правильность ответа, поддержка гипотезы и рыночный спрос не доказаны.");
 b.AppendLine().AppendLine("ПОЛНЫЙ СОХРАНЁННЫЙ ТЕКСТ ПОЛЯ — границы/неполнота указаны выше").AppendLine(S(m,"text"));string text=b.ToString();return new Row{Id=S(m,"id"),Kind=category,Label=label+": "+S(m,"url")+" | "+S(m,"source_field")+" | "+S(m,"captured_at"),Text=text,Search=text};}
 void AppendAnalysis(StringBuilder b,Dictionary<string,object>a){b.AppendLine().AppendLine("РУЧНОЙ РАЗБОР СОХРАНЁННЫХ МАТЕРИАЛОВ — не выполненный AI-анализ").AppendLine("Задача автора: "+S(a,"task")).AppendLine("Сравнение и неизвестное: "+S(a,"assessment")).AppendLine("Автоматическая проверка смысла: НЕ выполнена. Проверяются только ссылки, точные фрагменты и версии.");foreach(var f in Items(a,"supporting_document_fragments")){Dictionary<string,object>m;if(!materials.TryGetValue(S(f,"material_id"),out m))throw new InvalidDataException("Fragment material missing");int start=Convert.ToInt32(V(f,"start")),end=Convert.ToInt32(V(f,"end"));if(S(f,"text_sha256")!=S(m,"text_sha256")||ProvenanceAudit.Slice(S(m,"text"),start,end)!=S(f,"quote"))throw new InvalidDataException("Fragment binding mismatch");b.AppendLine("Фрагмент документа: "+S(m,"url")).AppendLine("codepoint ["+start+","+end+") | SHA256 текста: "+S(m,"text_sha256")).AppendLine(S(f,"quote")).AppendLine("Метка прежнего правила: "+S(f,"capability_label")+"; буквальное совпадение не доказывает полного покрытия задачи.");}
 if(!A(V(a,"document_ids")).Any())b.AppendLine("В этом сохранённом наборе подходящий документ не установлен; рынок целиком не проверен.");if(A(V(a,"unrelated_document_ids")).Any())b.AppendLine("Документы прежней маршрутизации без поддержки этой задачи: "+J(V(a,"unrelated_document_ids")));foreach(var err in A(V(a,"quote_errors")))b.AppendLine("Исключён неподтверждённый фрагмент: "+J(err));var n=D(V(a,"next_step"));b.AppendLine("СЛЕДУЮЩИЙ ШАГ — предложение ассистента, НЕ выполнен").AppendLine(S(n,"action")).AppendLine("Критерий успеха: "+S(n,"success")).AppendLine("Отрицательный результат: "+S(n,"failure")).AppendLine("Граница исполнения: "+S(n,"execution")).AppendLine("Переход к рынку: "+S(n,"market_gap")).AppendLine("Покупатель/оплата/спрос: НЕ установлены. Источник не объявлен клиентом пользователя.");}
 Row LegacyRow(Dictionary<string,object>h){string id=S(h,"id");var records=ManualHypotheses.A(new JavaScriptSerializer{MaxJsonLength=8388608}.DeserializeObject(File.ReadAllText(Path.Combine(root,"candidates.json"),Encoding.UTF8))).Select(D);var card=records.SingleOrDefault(x=>S(x,"candidate_id")==id);var b=new StringBuilder("СОХРАНЁННАЯ БИЗНЕС-ГИПОТЕЗА — исходный статус не изменён\r\n");b.AppendLine(S(h,"title")).AppendLine("ID: "+id+" | "+S(h,"status")).AppendLine("Это не проверенный бизнес, не клиент и не разрешение публикации. Решения владельца остаются отдельно.").AppendLine(J(V(h,"text")));if(card!=null)b.AppendLine(LegacyCandidateReviews.Describe(root,card));b.AppendLine("Дополнительные сохранённые поля по точным URL (не ретроактивный вход старой модели):");foreach(var value in ManualHypotheses.A(V(h,"material_ids"))){Dictionary<string,object>m;if(materials.TryGetValue(Convert.ToString(value),out m))b.AppendLine(S(m,"url")+" | "+S(m,"kind")+" | "+S(m,"id"));}b.AppendLine("При отсутствии тела исходника metadata/E-ID не объявляются его заменой.");string text=b.ToString();return new Row{Id=id,Kind="legacy",Label="Ранняя бизнес-гипотеза: "+S(h,"title"),Text=text,Search=text};}
 Row HypothesisRow(Dictionary<string,object>h){var b=new StringBuilder("ИСТОРИЧЕСКАЯ ГИПОТЕЗА МОДЕЛИ — смысловая поддержка НЕ доказана\r\n");b.AppendLine(S(h,"title")).AppendLine("ID: "+S(h,"id")+" | source job: "+S(h,"source_job")).AppendLine(J(V(h,"text"))).AppendLine("Связи означают только сохранённую привязку, не доказательство этих утверждений:");foreach(var id in A(V(h,"material_ids"))){Dictionary<string,object>m;if(!materials.TryGetValue(Convert.ToString(id),out m))throw new InvalidDataException("Hypothesis material missing");b.AppendLine(S(m,"url")+" | "+S(m,"id"));}b.AppendLine("Ручные разборы и следующие шаги открываются через исходное сообщение. Решение владельца хранится отдельно и здесь не меняется. AUTO_ADMISSION=false; клиентов/выручки не установлено.");string t=b.ToString();return new Row{Id=S(h,"id"),Kind="hypothesis",Label="Гипотеза модели: "+S(h,"title"),Text=t,Search=t};}
 void Filter(){string selected=(list.SelectedItem as Row)==null?"":((Row)list.SelectedItem).Id;string[] tokens=query.Text.Split(new[]{' ','\t','\r','\n'},StringSplitOptions.RemoveEmptyEntries);string k=kind.SelectedIndex==1?"original":kind.SelectedIndex==2?"document":kind.SelectedIndex==3?"hypothesis":kind.SelectedIndex==4?"archive":kind.SelectedIndex==5?"answer":kind.SelectedIndex==6?"package":kind.SelectedIndex==7?"metadata":kind.SelectedIndex==8?"manual":kind.SelectedIndex==9?"legacy":kind.SelectedIndex==10?"recovery":"";list.BeginUpdate();try{list.Items.Clear();foreach(var r in rows.Where(r=>(k==""||r.Kind==k||(k=="manual"&&r.Kind=="previous_manual"))&&tokens.All(t=>r.Search.IndexOf(t,StringComparison.OrdinalIgnoreCase)>=0)))list.Items.Add(r);for(int i=0;i<list.Items.Count;i++)if(((Row)list.Items[i]).Id==selected){list.SelectedIndex=i;break;}if(list.SelectedIndex<0&&list.Items.Count>0)list.SelectedIndex=0;if(list.Items.Count==0)detail.Text="Нет результатов локального поиска. Сеть не запрашивалась; это не отсутствие решений или спроса на рынке.";}finally{list.EndUpdate();}}
}
